class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        vector<int> ans;
        unordered_map<int,int> mp;
        for(int i =0;i<nums.size();i++){
            if(mp.find(target-nums[i])!=mp.end()){
                ans.push_back(mp[target-nums[i]]);
                ans.push_back(i);               
            }
            mp[nums[i]]=i;           
        }
        return ans;
    }
};,2,https://leetcode.com/problems/two-sum,https://leetcode.com/problems/two-sum/solutions/3109146/super-easy-solution/

class Solution
{
public:
    int carry = 0;
    ListNode *addTwoNumbers(ListNode *l1, ListNode *l2)
    {
        if (!l1 and !l2)
        {
            if (carry)
            {
                auto temp = new ListNode(carry);
                return temp;
            }
            return nullptr;
        }
        else if (l1 and l2)
        {
            l1->val += l2->val + carry;
            carry = l1->val / 10;
            l1->val = l1->val % 10;
            l1->next = addTwoNumbers(l1->next, l2->next);
        }
        else if (l1)
        {
            l1->val += carry;
            carry = l1->val / 10;
            l1->val = l1->val % 10;
            l1->next = addTwoNumbers(l1->next, nullptr);
            return l1;
        }
        else if (l2)
        {
            l2->val += carry;
            carry = l2->val / 10;
            l2->val = l2->val % 10;
            l2->next = addTwoNumbers(nullptr, l2->next);
            return l2;
        }
        return l1;
    }
};,3,https://leetcode.com/problems/add-two-numbers,https://leetcode.com/problems/add-two-numbers/solutions/1835535/java-c-a-very-beautiful-explanation-ever-exists/

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int n = s.length();
        int maxLength = 0;
        vector<int> charIndex(128, -1);
        int left = 0;

        for (int right = 0; right < n; right++) {
            if (charIndex[s[right]] >= left) {
                left = charIndex[s[right]] + 1;
            }
            charIndex[s[right]] = right;
            maxLength = max(maxLength, right - left + 1);
        }

        return maxLength;
    }
};,0,https://leetcode.com/problems/longest-substring-without-repeating-characters,https://leetcode.com/problems/longest-substring-without-repeating-characters/solutions/3649636/3-method-s-c-java-python-beginner-friendly/

public class Solution {
    public int LengthOfLongestSubstring(string s) {
        int i=0,count=0,maxCount=0;
        var m = new Dictionary<char, int>();
        for(int k=0;k<s.Length;k++){
            m[s[k]]=-1;
        }
        while(i<s.Length){
            if(m[s[i]]==-1){
                count++;
                m[s[i]]=i;
            }
            else{
                count=i-m[s[i]];
                foreach(var key in m.Keys.ToList()){
                    if(m[key]<m[s[i]]){
                        m[key]=-1;
                    }
                }
                m[s[i]]=i;
            }
            if(count>maxCount)
                maxCount=count;
            i++;
        }
        return maxCount;
    }
},5,https://leetcode.com/problems/longest-substring-without-repeating-characters,https://leetcode.com/problems/longest-substring-without-repeating-characters/solutions/3160786/c/

class Solution {
public:
    bool isMatch(string s, string p) {
        int m = s.size(), n = p.size();
        vector<bool> cur(n + 1, false);
        for (int i = 0; i <= m; i++) {
            bool pre = cur[0];
            cur[0] = !i;
            for (int j = 1; j <= n; j++) {
                bool temp = cur[j];
                if (p[j - 1] == '*') {
                    cur[j] = cur[j - 2] || (i && cur[j] && (s[i - 1] == p[j - 2] || p[j - 2] == '.'));
                } else {
                    cur[j] = i && pre && (s[i - 1] == p[j - 1] || p[j - 1] == '.');
                }
                pre = temp;
            }
        }
        return cur[n];
    }
};,19,https://leetcode.com/problems/regular-expression-matching,https://leetcode.com/problems/regular-expression-matching/solutions/5684/c-o-n-space-dp/

class Solution {
public:
    int maxArea(vector<int> &height) {
        int i = 0, j = height.size() - 1, area = 0;
        while (i < j) {
            area = max(area, min(height[i], height[j]) * (j - i));
            height[i] < height[j] ? i++ : j--;
        }
        return area;
    }
