class Solution {
public:
    int strStr(string h, string n) {
        int n1=h.size(),n2=n.size();
        if(n2>n1){
            return -1;
        }
        for(int i=0;i<=(n1-n2);i++){
            if(h[i]==n[0]){
                int j;
                for(j=i;j<i+n2;j++){
                    if(h[j]!=n[j-i]){
                        break;
                    }
                }
                if(j==i+n2){return i;}
            }
        }
        return -1;
    }
};,46,https://leetcode.com/problems/implement-strstr,https://leetcode.com/problems/find-the-index-of-the-first-occurrence-in-a-string/solutions/4417673/c-simple-easy-to-understand/

class Solution {
public:
    int longestValidParentheses(string s) {
        stack<int> st;
        st.push(-1);
        int cnt = 0;
        for(int i=0;i<s.size();i++){
            if(s[i] == '(')
                st.push(i);
            else{
                if(!st.empty()){
                    st.pop();
                }
                if(!st.empty()){
                    cnt = max(cnt , i - st.top());
                }
                else 
                    st.push(i);
            }
        }
        return cnt;
    }
};,17,https://leetcode.com/problems/longest-valid-parentheses,https://leetcode.com/problems/longest-valid-parentheses/solutions/4414802/stack-easiest-code/

class Solution {
public:
    int search(vector<int>& A, int B) {
        int l = 0;
        int r = A.size() - 1;
        int m;
        while (l <= r) {
            m = (l + r) / 2;
            if (A[m] == B) return m;
            if (A[m] >= A[0]) {
                if (B >= A[0] && B <= A[m]) r = m - 1;
                else l = m + 1;
            } else {
                if (B >= A[m] && B <= A[A.size() - 1]) l = m + 1;
                else r = m - 1;
            }
        }
        return -1;
    }
};,52,https://leetcode.com/problems/search-in-rotated-sorted-array,https://leetcode.com/problems/search-in-rotated-sorted-array/solutions/3879481/beats-100-video-solution-java-c-python/

class Solution {
    private int[] line = new int[9];
    private int[] column = new int[9];
    private int[][] block = new int[3][3];
    private boolean valid = false;
    private List<int[]> spaces = new ArrayList<int[]>();

    public void solveSudoku(char[][] board) {
        for (int i = 0; i < 9; ++i) {
            for (int j = 0; j < 9; ++j) {
                if (board[i][j] != '.') {
                    int digit = board[i][j] - '0' - 1;
                    flip(i, j, digit);
                }
            }
        }

        while (true) {
            boolean modified = false;
            for (int i = 0; i < 9; ++i) {
                for (int j = 0; j < 9; ++j) {
                    if (board[i][j] == '.') {
                        int mask = ~(line[i] | column[j] | block[i / 3][j / 3]) & 0x1ff;
                        if ((mask & (mask - 1)) == 0) {
                            int digit = Integer.bitCount(mask - 1);
                            flip(i, j, digit);
                            board[i][j] = (char) (digit + '0' + 1);
                            modified = true;
                        }
                    }
                }
            }
            if (!modified) {
                break;
            }
        }

        for (int i = 0; i < 9; ++i) {
            for (int j = 0; j < 9; ++j) {
                if (board[i][j] == '.') {
                    spaces.add(new int[]{i, j});
                }
            }
        }

        dfs(board, 0);
    }

    public void dfs(char[][] board, int pos) {
        if (pos == spaces.size()) {
            valid = true;
            return;
        }

        int[] space = spaces.get(pos);
        int i = space[0], j = space[1];
        int mask = ~(line[i] | column[j] | block[i / 3][j / 3]) & 0x1ff;
        for (; mask != 0 && !valid; mask &= (mask - 1)) {
            int digitMask = mask & (-mask);
            int digit = Integer.bitCount(digitMask - 1);
            flip(i, j, digit);
            board[i][j] = (char) (digit + '0' + 1);
            dfs(board, pos + 1);
            flip(i, j, digit);
        }
    }

    public void flip(int i, int j, int digit) {
        line[i] ^= (1 << digit);
        column[j] ^= (1 << digit);
        block[i / 3][j / 3] ^= (1 << digit);
    }
}
,18,https://leetcode.com/problems/sudoku-solver,https://leetcode.com/problems/sudoku-solver/solutions/4280602/beats-100-of-users-with-java-in-runtime-99-85-in-memory-unveiling-sudoku-secrets-o-n-tc/

class Solution {
public:
    bool safe(int row,int col,vector<vector<char>>& board,char c){
        for(int i = 0; i < 9;i++){
            if(board[row][i] == c) return false;

            if(board[i][col] == c) return false;

            if(board[3*(row/3) + (i/3)][3*(col/3) + (i%3)] == c) return false;

        }
        return true;
    }

    bool solve(vector<vector<char>>& board){
        int n = board[0].size();

        for(int i = 0; i < n ; i++){
            for(int j = 0; j < n;j++){
                if(board[i][j] == '.'){
                    for(char c = '1'; c <= '9';c++){
                        if(safe(i,j,board,c)){
                            board[i][j] = c;
                            bool possible = solve(board);
                            if(possible){
                                return true;
                            }
                            else{
                                board[i][j] = '.';
                            }
                        }     
                    }
                    return false;
                }

            }
        }
        return true;
    }
    void solveSudoku(vector<vector<char>>& sudoku) {
        solve(sudoku);
    }
};,54,https://leetcode.com/problems/sudoku-solver,https://leetcode.com/problems/sudoku-solver/solutions/3900934/easy-c-solution-using-backtracking/

