    }
    void help(int i,int t,List<Integer> ll,int[] a){
        if(t==0){
            l.add(new ArrayList<>(ll));
            return;
        }
        if(i>=a.length){
           return;
        }


    if(t>=a[i]){
    ll.add(a[i]);
    help(i,t-a[i],ll,a);
    ll.remove(ll.size()-1);
    }
    help(i+1,t,ll,a);
    }
