using int2=pair<int, int>;
class Solution {
public:
    int n;
    vector<vector<int>> result;
    void backtrack(int i, vector<int>& subset, vector<int2>& nWm, int target) {
        if (target == 0) {
            result.push_back(subset);
            return;
        }

        if (i == n || target < 0) {
            return;
        }

        auto [x, m] = nWm[i];
        for (int j = 0; j <= m; j++) {
            for (int k = 1; k <= j; k++) // Add j x's to subset
                subset.push_back(x);

            backtrack(i + 1, subset, nWm, target-j*x);

            for (int k = 1; k <= j; k++) //backtracking
                subset.pop_back();    
        }
    }

    vector<vector<int>> combinationSum2(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());
        vector<int2> nWm;
        nWm.push_back({candidates[0], 1});
        int idx = 0;
        for (int i = 1; i < candidates.size(); i++) {
            if (candidates[i] == candidates[i-1]) {
                nWm[idx].second++;
            } 
            else {
                nWm.push_back({candidates[i], 1});
                idx++;
            }
        }

        n=nWm.size();
        vector<int> subset;
        backtrack(0, subset, nWm, target);
        return result;
    }
};,49,https://leetcode.com/problems/combination-sum-ii,https://leetcode.com/problems/combination-sum-ii/solutions/3812563/c-backtracking-considering-multiplicities-vs-dp/

class Solution {
public:
    string multiply(string num1, string num2) {
        if (num1 == "0" || num2 == "0") return "0";

        vector<int> res(num1.size()+num2.size(), 0);

        for (int i = num1.size()-1; i >= 0; i--) {
            for (int j = num2.size()-1; j >= 0; j--) {
                res[i + j + 1] += (num1[i]-'0') * (num2[j]-'0');
                res[i + j] += res[i + j + 1] / 10;
                res[i + j + 1] %= 10;
            }
        }

        int i = 0;
        string ans = "";
        while (res[i] == 0) i++;
        while (i < res.size()) ans += to_string(res[i++]);

        return ans;
    }
};,62,https://leetcode.com/problems/multiply-strings,https://leetcode.com/problems/multiply-strings/solutions/1563507/c-simple-easy-and-short-solution-brief-explanation/

class Solution {
public:
    void permutations(int idx, vector<int>& nums, vector<vector<int>>& ans) {
        if (idx == nums.size()) {
            ans.push_back(nums);
            return;
        }
        for (int i = idx; i < nums.size(); i++) {
            swap(nums[idx], nums[i]);
            permutations(idx+1, nums, ans);
            swap(nums[idx], nums[i]);
        }
    }
    vector<vector<int>> permute(vector<int>& nums) {
        vector<vector<int>> ans;
        permutations(0, nums, ans);
        return ans;
    }
};,24,https://leetcode.com/problems/permutations,https://leetcode.com/problems/permutations/solutions/3957700/best-solution/

class Solution {
private:
    void backTrack(vector<vector<int>>& res, vector<int>& curr, unordered_map<int,int>& m, vector<int>& nums) {
        if(curr.size() == nums.size()) {
            res.push_back(curr);
        }

        for(auto itr = m.begin(); itr != m.end(); itr++) {
            if(itr->second == 0) continue;
            curr.push_back(itr->first);
            itr->second -= 1;
            backTrack(res, curr, m, nums);
            curr.pop_back();
            itr->second += 1;
        }
    }
public:
    vector<vector<int>> permuteUnique(vector<int>& nums) {
        vector<vector<int>> res;
        vector<int> curr;
        unordered_map<int,int> m;
        for(int i = 0; i < nums.size(); i++) {
            m[nums[i]]++;
        }
        backTrack(res, curr, m, nums);
        return res;
    }
};,59,https://leetcode.com/problems/permutations-ii,https://leetcode.com/problems/permutations-ii/solutions/3712389/c-backtracking-using-hash-table/

class Solution {
public:
    vector<vector<string>> groupAnagrams(vector<string>& v) {
        int m=v.size();

        map<map<char,int>,vector<string>> bm;

        for(int i=0;i<m;i++){
            map<char,int> sm;

            string s=v[i];
            int n=s.length();

            for(int i=0;i<n;i++){
                char ch=s[i];
                sm[ch]++;
            }

            vector<string> cur;
            if(bm.find(sm)!=bm.end()) cur=bm[sm];
            cur.push_back(s);

            bm[sm]=cur;
        }

        vector<vector<string>> ans;

        for(auto it=bm.begin();it!=bm.end();it++){
            vector<string> cur=it->second;

            ans.push_back(cur);
        }

        return ans;
    }
};,69,https://leetcode.com/problems/group-anagrams,https://leetcode.com/problems/group-anagrams/solutions/3747969/c-hash-map/

public class Solution {
    public double MyPow(double x, int n) {
        long N = n;
        if (N == 0) return 1;
        if (N < 0) {
            x = 1 / x;
            N = -N;
        }
        return CalculatePow(x, N);
    }
    private double CalculatePow(double x, long n) {
        if (n == 1) return x;
        double halfPow = CalculatePow(x, n / 2);
        return n % 2 == 0 ? halfPow * halfPow : halfPow * halfPow * x;
    }
},9,https://leetcode.com/problems/powx-n,https://leetcode.com/problems/powx-n/solutions/3807836/c-solution-for-pow-x-n-problem/

class Solution {
public:
    bool isSafe(int row, int cols, vector<vector<int>>& board, int n){
        int i = row, j = cols;

        //left row check
        while(j >= 0){
            if(board[i][j] == 1){
                return false;
            }
            j--;
        }

        //upper left diagonal check
        i = row; j = cols;
        while(i >= 0 && j >= 0){
            if(board[i][j] == 1){
                return false;
            }
            i--; j--;
        }

        //bottom left diagonal
        i = row; j = cols;
        while(i < n && j >= 0){
            if(board[i][j] == 1){
                return false;
            }
            i++; j--;
        }

        return true;
    }


    int solve(vector<vector<int>>& board, int n, int cols, int& count){
        //base case
        if(cols >= n){
            count++;
            return count;
        }

        //ek case solve kardo
        for(int row=0; row<n; row++){
            if(isSafe(row, cols, board, n)){
                board[row][cols] = 1;
                solve(board, n, cols+1, count);
                board[row][cols] = 0;
            }
        }

        return count;
    }

    int totalNQueens(int n) {
        // if(n <= 3){
        //     return 0;
        // }
        int count = 0;
        vector<vector<int>> board(n, vector<int>(n, 0));
        return solve(board, n, 0, count);
    }
