class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        int n=matrix.size();
        int m=matrix[0].size();
        int A=0,up=0,down=n-1,left=0,right=m-1;
        vector<int>res;
        while(left<=right && up<=down)
        {
        if(A==0)
        {

            for(int i=left;i<=right;i++)
                res.push_back(matrix[up][i]);
            up++;
            A=1;
        }
        else if(A==1)
        {

            for(int i=up;i<=down;i++)
            res.push_back(matrix[i][right]);
            right--;
            A=2;
        }
        else if(A==2)
        {
            for(int i=right;i>=left;i--)
                res.push_back(matrix[down][i]);
            down--;
            A=3;

        }
        else if(A==3)
        {

            for(int i=down;i>=up;i--)
                res.push_back(matrix[i][left]);
            left++;
            A=0;


        }

        }
        return res;
    }
};,80,https://leetcode.com/problems/spiral-matrix,https://leetcode.com/problems/spiral-matrix/solutions/3503590/c-beats-100/

class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        int n=intervals.size();
        //Firstly, sort intervals 
        sort(intervals.begin(),intervals.end());
        vector<vector<int>> ans;
        for(int i=0;i<n;i++){
            //If we are pushing the first interval or the next interval's starting is greater than last interval's ending, just push that interval to ans
            if(ans.empty() || intervals[i][0]> ans.back()[1]){
                ans.push_back(intervals[i]);
            }
            //Otherwise, the ending point of last interval would be updated to the maximum of both possible ending points
            else{
                ans.back()[1]=max(ans.back()[1], intervals[i][1]);
            }
        }

        return ans;        
    }
};,10,https://leetcode.com/problems/merge-intervals,https://leetcode.com/problems/merge-intervals/solutions/4322157/c-solution-with-explanation/

class Solution {
public:
    int uniquePaths(int m, int n) {
        vector<vector<int>> dp(m, vector<int>(n, 1));
        for(int i = 1; i < m; i++)
            for(int j = 1; j < n; j++)
                dp[i][j] = dp[i-1][j] + dp[i][j-1];   // sum of unique paths ending at adjacent top and left cells
        return dp[m-1][n-1];         // return unique paths ending at cell (m-1, n-1)
    }
