class Solution {
    public int uniquePaths(int m, int n) {
        int[][] dp = new int[m][n];
        for(int row = 0; row < m; row++)
            dp[row][0] = 1;//only 1 way to get to 0th col, from the top down
        for(int col = 0; col < n; col++)
            dp[0][col] = 1;//only 1 way to get to 0th row, from the top left

        for(int row = 1; row < m; row++) {
            for(int col = 1; col < n; col++) {
                dp[row][col] = dp[row-1][col] + dp[row][col-1];
            }
        }
        return dp[m-1][n-1];
    }
