            a = a.slice(0,-1);
        }
        if(b!="") {
            y = parseInt(b.slice(-1));
            b = b.slice(0,-1);
        }
        if(x+y+rem == 2) {
            rem=1;
            res = "0" + res;
        }
        else if(x+y+rem == 3) {
            rem=1;
            res = "1" + res;
        }
        else {
            res = (x+y+rem).toString() + res;
            rem=0;
        }
        x=0;
        y=0;
    }
    if(rem==1) res = "1" + res;
    return res;

