/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    // time/space: O(n)/O(1)
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> result;
        TreeNode* curr = root;
        while (curr != NULL) {
            if (curr->left == NULL) {
                result.push_back(curr->val);
                curr = curr->right;
            }
            else {
                // find the right-most node from the left node
                TreeNode* node = curr->left;
                while ((node->right != NULL) && (node->right != curr)) node = node->right;

                // magic
                if (node->right == NULL) {
                    // connect to the current node `curr`
                    node->right = curr;
                    curr = curr->left;
                }
                else {
                    // revert the connection
                    node->right = NULL;
                    // the left nodes of the current node `curr` are all done
                    result.push_back(curr->val);
                    curr = curr->right;
                }
            }
        }
        return result;
    }
};,111,https://leetcode.com/problems/binary-tree-inorder-traversal,https://leetcode.com/problems/binary-tree-inorder-traversal/solutions/4380353/c-morris-traversal-without-extra-space/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<TreeNode*> solve(int start,int end){
        vector<TreeNode*> ans;
        if(start>end){
            ans.push_back(NULL);
            return ans;
        }
        for(int i=start;i<=end;i++){
            auto left=solve(start,i-1);
            auto right=solve(i+1,end);
            for(auto l:left){
                for(auto r:right){
                    TreeNode* newNode=new TreeNode(i);
                    newNode->left=l;
                    newNode->right=r;
                    ans.push_back(newNode);
                }
            }
        }
        return ans;
    }
    vector<TreeNode*> generateTrees(int n) {
        return solve(1,n);
    }
