class Solution {
    public Node connect(Node root) {
        if(root==null)return root;

        Queue<Node> q=new LinkedList();
        q.offer(root);
        while(!q.isEmpty())
        {
            int n=q.size();
            Node prev=null;
            for(int i=0;i<n;i++)
            {
                Node top=q.poll();
                top.next=prev;
                prev=top;
                if(top.right!=null)
                    q.offer(top.right);
                if(top.left!=null)
                    q.offer(top.left);           
            }
        }
      return root;  
    }
