        //     dp[n][0][i] = 0;
        //     dp[n][1][i] = 0;
        // }
        for(int i=n-1;i>=0;i--){
            for(int j=1;j>=0;j--){
                for(int k=2;k>0;k--){
                    if(j == 0)
                        dp[i][j][k] = max(-prices[i]+dp[i+1][1][k],dp[i+1][0][k]);
