    {
        if (!root) return;

        if (!root->left && !root->right) 
        {
            sum += num * 10 + root->val;
            return;
        }

        num = num * 10 + root->val;

        dfs(root->left, sum, num);
        dfs(root->right, sum, num);

        num /= 10;
    }
    int sumNumbers(TreeNode* root) {
        int sum = 0;
        int num = 0;

        dfs(root, sum, num);

        return sum;
    }
