class Solution {
public:
    vector<vector<string>> partition(string s) {
        vector<vector<string>> res; vector<string> par;

        auto isPalindrome = [&s](int l, int r) {
            while (l < r) if (s[l++] != s[r--]) return false;
            return true;
        };

        function<void(int)> part = [&](auto start) {
            if (start == s.size()) res.push_back(par);
            else 
                for (auto i = start; i < s.size(); i++) 
                    if (isPalindrome(start, i)) {
                        par.push_back(s.substr(start, i - start + 1));
                        part(i + 1);
                        par.pop_back();
                    }
        };
        part(0);
        return res;
    }
};,128,https://leetcode.com/problems/palindrome-partitioning,https://leetcode.com/problems/palindrome-partitioning/solutions/3084180/dfs-10-lines-only-99-faster/

class Solution {
    public int minCut(String s) {
        boolean[][] isPalindrome=new boolean[s.length()][s.length()];
        for(int gap=0; gap<isPalindrome.length ; gap++){
            for(int i=0 ,j=gap; j<isPalindrome[0].length ;i++, j++){
                 if(gap==0){
                    isPalindrome[i][j]=true;
                 }else if(gap==1){
                     isPalindrome[i][j]=(s.charAt(i)==s.charAt(j));
                 }else{
                    if(s.charAt(i)==s.charAt(j) && isPalindrome[i+1][j-1]){
                        isPalindrome[i][j]=true;
                    }else{
                        isPalindrome[i][j]=false;
                    }
                 }
            }
        }
        int[] dp=new int[s.length()];
        dp[0]=0;
        for(int i=1; i<dp.length; i++){
            if(isPalindrome[0][i]){
                dp[i]=0;
            }else{    
                int min=Integer.MAX_VALUE;
                for(int j=i; j>=1; j--){
                    if(isPalindrome[j][i]){
                       min=Math.min(min,1+dp[j-1]);
                    }
                }
                dp[i]=min;
            }
        }
        return dp[dp.length-1];
    }
