class LRUCache
    attr_reader :cache, :capacity

    def initialize(capacity)
        @cache, @capacity = {}, capacity
    end


    def get(key)
        if (v = cache.delete(key)).nil? then
            -1
        else
            @cache.update(key => v)
            v
        end
    end

    def put(key, value)
        d = @cache.delete(key).nil? ? 1 : 0
        @cache.shift if cache.size + d > capacity
        @cache.update(key => value)
    end
