class Solution {
public:
    int findPeak(vector<int> &nums)
{
    int n = nums.size();
    int lb = 0;
    int ub = n - 1;

    while (lb <= ub)
    {
        int mid = lb + (ub - lb) / 2;
        if ((mid - 1 >= 0 and nums[mid] > nums[mid - 1]) and (mid + 1 < n and nums[mid] > nums[mid + 1]))
        {
            return mid;
        }
        else if (nums[mid] < nums[0])
        {
            ub = mid - 1;
        }
        else
        {
            lb = mid + 1;
        }
    }

    return max(0, ub);
}

