class Trie {
private:
    struct Node{
    public:
        Node* links[26];
        bool flag;
        function<bool(char)>contains = [&](char e){return links[e-'a']!=NULL;};
        function<void(char,Node*)> add = [&](char e,Node* node){links[e-'a'] = node;};
        function<Node*(char)> get = [&](char e){return links[e-'a'];};
        function<void()> setEnd = [&](){this->flag = true;};
        function<bool()> isEnd = [&](){return this->flag;};
    };
private:
    Node* root;
public:
    Trie() {
        root = new Node();
    }

    void insert(string word) {
        Node *node  = root;
        for(char&e: word){
            if(!node->contains(e))
                node->add(e,new Node());
            node = node->get(e);
        }
        node->setEnd();
    }

    bool search(string word) {
        Node *node = root;
        for(char&e: word){
            if(!node->contains(e)) return false;
            node = node->get(e);
        }
        return node->isEnd();
    }

    bool startsWith(string prefix) {
        Node *node = root;
        for(char&e: prefix){
            if(!node->contains(e)) return false;
            node = node->get(e);
        }
        return true;
    }
};,28,https://leetcode.com/problems/implement-trie-prefix-tree,https://leetcode.com/problems/implement-trie-prefix-tree/solutions/3634606/concise-c-code/

