class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {

        int n=nums.size();
        int res=1e9;

        int sum=0,k=0;


        for(int i=0;i<n;i++){
            sum+=nums[i];

            while(sum>=target){

                res=min(res,i-k+1);
                sum-=nums[k];
                k++;
            }
        }

        return (res==1e9)?0:res;
    }
