class MedianFinder {
public:

    multiset<int> numbers;    
    void addNum(int num) {
        numbers.insert(num);
    }

    double findMedian() {
        int sz=numbers.size();
        int k=(sz-1)/2;
        auto it=numbers.begin();
        advance(it,k);
        double ans = *it;
        if(sz%2==0){
            if(++it!=numbers.end()){
                ans+= *it;
                ans=ans/2;
            }
        }
        return ans;
    }
