class Solution:
    def merge(self, intervals):
        intervals.sort(key=lambda x: x[0])
        merged = []

        for interval in intervals:
            if not merged or merged[-1][1] < interval[0] - 1:
                merged.append(interval)
            else:
                merged[-1][1] = max(merged[-1][1], interval[1])

        return merged


    def minPatches(self, nums, n):
        ints, patches = [[0,0]], 0
        for num in nums:
            ints = self.merge(ints + [[i+num, j+num] for i,j in ints])

        while ints[0][1] < n:
            ints = self.merge(ints + [[i+ints[0][1]+1, j+ints[0][1]+1] for i,j in ints])
            patches += 1

        return patches,106,https://leetcode.com/problems/patching-array,https://leetcode.com/problems/patching-array/solutions/1432422/python-2-solutions-merge-intervals-greedy-explained/

class Solution {
public:
    bool increasingTriplet(vector<int>& nums) {

        int n = nums.size();

        // left_min[i] will store the minimum from left till ith

        vector<int> left_min(n);

        // right_max[i] will store the maximum from right till ith

        vector<int> right_max(n);

        // fill left_min array

        left_min[0] = nums[0];

        for(int i = 1; i < n; i++)
        {
            left_min[i] = min(left_min[i - 1], nums[i]);
        }

        // fill right_max array

        right_max[n - 1] = nums[n - 1];

        for(int i = n - 2; i >= 0; i--)
        {
            right_max[i] = max(right_max[i + 1], nums[i]);
        }

        // check that is there any element which has smaller element on left side and greater element on right side

        for(int i = 1; i < n - 1; i++)
        {
            if(left_min[i - 1] < nums[i] && nums[i] < right_max[i + 1])
            {
                return true;
            }
        }

        return false;
    }
};,23,https://leetcode.com/problems/increasing-triplet-subsequence,https://leetcode.com/problems/increasing-triplet-subsequence/solutions/2688485/two-approaches-easy-to-understand-c-code/

class Solution {
    public int[] countBits(int n) {
        int res[] = new int[n + 1]; // create one result array, 
        // & our array size is n + 1 because we have to cover 0 as well

        for(int i = 0; i <= n; i++){ // run a loop to store all the values we get from a solve function
            res[i] = solve(i);
        }
        return res;
    }
    public int solve(int n){
        // base condition
        if(n == 0) return 0;
        if(n == 1) return 1;

        if(n % 2 == 0) return solve(n / 2); // handling even case
        else return 1 + solve(n / 2); // handling odd case
    }
