        for(int i = 0 ;i<nums.size();i++)
            m[nums[i]]++; 
        vector<pair<int,int>> v;
        for(auto x : m)
            v.push_back(make_pair(x.second,x.first));
        sort(v.begin(),v.end(),cmp);
        for(auto x : v){
            if(k==0)
                return res ; 

                res.push_back(x.second);
            k--;


        }
        return res ; 
