class Node{

	public:
	Node* links[2];
};
class Trie{

	public:
	Node* root;
	Trie(){
		root=new Node();
	}
	void insert(int num){
		Node* node=root;
		for(int i=31; i>=0; i--){
			int bit=(num>>i)&1;
			if(!node->links[bit]){
				node->links[bit]=new Node();
			}
			node=node->links[bit];
		}
	}
	int maxnum(int num){
		Node* node=root;
		int maxi=0;
		for(int i=31; i>=0; i--){
			int bit=(num>>i)&1;
			if(!node->links[1-bit]){
				node=node->links[bit];
			}
			else{
				maxi=maxi|(1<<i);
				node=node->links[1-bit];
			}
		}
		return maxi;
	}
};

