var originalDigits = function (s) {
  let arr = [
    // from top to bottom
    // [digit, digit in words,  'unique letter' in 'digit in words'  ]
    [0, "zero", "z"], // z is unique letter in zero - if we see from top to bottom of this list
    [6, "six", "x"], //  x is unique letter in six - if we see from top to bottom
    [2, "two", "w"], //  w is unique letter in two
    [8, "eight", "g"],
    [4, "four", "u"],
    [3, "three", "r"],
    [5, "five", "f"],
    [7, "seven", "v"],
    [9, "nine", "i"],
    [1, "one", "o"],
  ];

  let f = {} // frequency of every char
  for (let ch of s)
    f[ch] = (f[ch] || 0) + 1    // calc frequency of every char of every word

  let an = [];
  for (let [n, w, uniq_char_in_w] of arr) {

    // while a new next digit is repeatedly found
    while (f[uniq_char_in_w]) {
      // found this digit ( again )
      an.push(n);

      // remove this digit's word frequency
      for (let ch of w)
        f[ch] = (f[ch] || 0) - 1
    }
  }

  // all digits found
  an.sort((a, b) => a - b);

  return an.join(""); // return as string
};
