class Codec {
public:

    // Encodes a tree to a single string.
    string serialize(TreeNode* root) {
        return encode(root);
    }

    // Decodes your encoded data to tree.
    TreeNode* deserialize(string data) {
        stringstream ss(data);
        string item;
        TreeNode* root = NULL;

        while (getline (ss, item, '-')) 
            root = insert(root, stoi(item));

        return root;
    }

private:
    string encode(TreeNode* root) {
        if (!root)
            return "";
        return to_string(root->val) + "-" + encode(root->left)+encode(root->right);
    }

    TreeNode* insert(TreeNode* root, int val) {
        if (root == NULL) {
			TreeNode* temp=new TreeNode(val);
			return temp;
		}

		if (val<=root->val)
			root->left=insert(root->left,val);

		else
			root->right=insert(root->right,val);

		return root;
    }
};,62,https://leetcode.com/problems/serialize-and-deserialize-bst,https://leetcode.com/problems/serialize-and-deserialize-bst/solutions/886396/c-simple-and-clean-preorder-traversal-solution/

class Solution {
public:
    TreeNode* deleteNode(TreeNode* root, int key) {
        if(!root) return nullptr;
		// search for key node
        if(root -> val < key) root -> right = deleteNode(root -> right, key);
        else if(root -> val > key) root -> left = deleteNode(root -> left, key);
        else { // root -> val == key
            auto toDelete = root;
            if(!root -> left || !root -> right) 
                root = root -> left ? root -> left : root -> right;
            else {
				auto cur = root, par = root;
                root = root -> right;
                while(root -> left) par = root, root = root -> left;  // finding smallest in right subtree
                cur -> val = root -> val;                             // replace node to be deleted- cur with value of smallest node found
				// take care of child node...same as above
                if(par -> left == root) par -> left = root -> right;
                else par -> right = root -> right;
				toDelete = root;
                root = cur;
            }
            delete toDelete;            			
        }
        return root;
    }
};,63,https://leetcode.com/problems/delete-node-in-a-bst,https://leetcode.com/problems/delete-node-in-a-bst/solutions/1591176/c-simple-solution-w-images-detailed-explanation-iterative-recursive-approach/

