                            count++;
                    // down
                    if(i+1>=grid.Length)
                        count++;
                    else
                        if(grid[i+1][j]==0)
                            count++;
                    // left
                    if(j-1<0)
                        count++;
                    else
                        if(grid[i][j-1]==0)
                            count++;
                    // right
                    if(j+1>=grid[i].Length)
                        count++;
                    else
                        if(grid[i][j+1]==0)
                            count++;
                }
            }
        }
        return count;
    }
