class Solution {
public:

    int solve(int l, int r, string &s,vector<vector<int>> &res)
    {
        if(l>=s.length() || r<0)
            return 0;
        if(res[l][r]!=-1)
            return res[l][r];
        if(s[l] == s[r])
            return res[l][r] = 1+(solve(l+1,r-1,s,res));
        else
        {
            return (res[l][r] = max(solve(l,r-1,s,res),solve(l+1,r,s,res)));
        }
    }
    int longestPalindromeSubseq(string s) {
        int n = s.length()-1;
        vector<vector<int>> res(n+1,vector<int>(n+1,-1));
        return solve(0,n,s, res);
    }
