            for(int j=1;j<=m;j++)
            {
                if(s.charAt(i-1) == p.charAt(j-1))
                {
                    dp[j] = 1 + de[j-1];
                }
                else
                {
                    dp[j] = Math.max(dp[j-1] , de[j]);
                }
            }
            for(int j=1;j<=m;j++)
            {
                de[j] = dp[j];
            }
        }
        return de[m];
    }
