class Solution {
public:
    int dp[1001][1002];
    int helper(int ind, int n, vector<vector<int>>& pairs, int prev){
        if(ind == n)
            return 0;
        if(dp[ind][prev + 1] != -1)
            return dp[ind][prev + 1];
        int ans = 0;
        if(prev == -1 ||  pairs[ind][0] > pairs[prev][1])
            ans = max(ans, 1 + helper(ind + 1, n, pairs, ind));
        ans = max(ans, helper(ind + 1, n, pairs, prev));
        return dp[ind][prev + 1] = ans;
    }
    int findLongestChain(vector<vector<int>>& pairs) {
        sort(pairs.begin(),pairs.end());
        int n = pairs.size();
        memset(dp, -1, sizeof(dp));
        return helper(0, n, pairs, -1);
    }
