class Solution {
    vector<vector<int>> dp;
public:
    int maxProfit(vector<int>& prices, int fee) {
        int n = prices.size();
        dp = vector<vector<int>> (n+1, vector<int>(2));

        dp[n][0] = dp[n][1] = 0; // base case

        for (int i=n-1; i>=0; i--) {
            for (int buy=0; buy<=1; buy++) {
                if (buy) {
                    int x = dp[i+1][0] - prices[i] - fee; // buy
                    int y = dp[i+1][1]; // don't buy
                    dp[i][buy] = max(x, y);
                }
                else {
                    int x = dp[i+1][1] + prices[i]; // sell
                    int y = dp[i+1][0]; // don't sell
                    dp[i][buy] = max(x, y);
                }
            }
        }

        return dp[0][1];
    }
