class Solution {
public:
    vector<ListNode*> splitListToParts(ListNode* head, int k) {
        ListNode *cur = head;
        vector<ListNode*> answer(k) ;
        int ptr = 0, listLength = 0;

        // Calculate the length of the linked list
        while (cur != nullptr) {
            listLength++;
            cur = cur->next;
        }

        // Calculate the extra elements in some parts
        int extra = listLength % k;
        // Calculate the base length for each part
        int partLength = listLength / k;
        cur = head;

        while (cur != nullptr) {
            answer[ptr++] = cur;
            // Calculate the length of the current part
            int currentLength = partLength - 1 + ((extra-- > 0) ? 1 : 0);

            // Move the current pointer to the end of the current part
            for (int i = 0; i < currentLength; i++)
                cur = cur->next;

            // Disconnect the current part from the next part
            ListNode *temp = cur->next;
            cur->next = nullptr;
            cur = temp;
        }
        return answer;
    }
};,148,https://leetcode.com/problems/split-linked-list-in-parts,https://leetcode.com/problems/split-linked-list-in-parts/solutions/4007761/java-100-time-0ms-c-6ms-two-pass-solution/

class Solution(object):
    def countOfAtoms(self, formula):
        import re
        from collections import defaultdict
        tokens = list(filter(lambda c: c, re.split('([A-Z]{1}[a-z]?|\(|\)|\d+)', formula)))
        stack, i = [defaultdict(int)], 0
        while i < len(tokens):
            token = tokens[i]
            if token == '(':
                stack.append(defaultdict(int))
            else:
                count = 1
                # Check if next token is a number.
                if i + 1 < len(tokens) and re.search('^\d+$', tokens[i + 1]):
                    count, i = int(tokens[i + 1]), i + 1
                atoms = stack.pop() if token == ')' else { token: 1 }
                # Combine counts of atoms.
                for atom in atoms:
                    stack[-1][atom] += atoms[atom] * count
            i += 1
