class Solution {
public:
    int shortestPathLength(vector<vector<int>>& graph) {
        int n = graph.size();
        int mask = (1<<n) - 1;
        queue<pair<int,pair<int,int>>> q;

        vector<vector<bool>> visited(mask + 1, vector<bool>(n, false));

        for (int node = 0; node < n; ++node) {
            int origMask = (1 << node);
            q.push({node, {origMask, 1}});
            visited[origMask][node] = true;
        }


        while (!q.empty()) {
            auto curr = q.front();
            q.pop();

            int currNode = curr.first;
            int currMask = curr.second.first;
            int currLength = curr.second.second;

            if (currMask == mask)
                return currLength - 1;

            for (int i = 0; i < graph[currNode].size(); ++i) {
                int neighbor = graph[currNode][i];
                int newMask = currMask | (1 << neighbor);

                if (visited[newMask][neighbor])
                    continue;

                q.push({neighbor, {newMask, currLength + 1}});
                visited[newMask][neighbor] = true;
            }
        }
        return -1;  
    }
};,105,https://leetcode.com/problems/shortest-path-visiting-all-nodes,https://leetcode.com/problems/shortest-path-visiting-all-nodes/solutions/4053647/98-28-with-proper-and-concise-explanation/

class Solution {
    public int maxDistToClosest(int[] seats) {
        int pre_zeros = -1, suf_zeros = -1, max_zeros = -1, zeros = 0;
        for (int i = 0; i < seats.length; i ++) {
            if (seats[i] == 0) {
                zeros ++;
            } else {
                if (pre_zeros == -1) {
                    pre_zeros = zeros;
                } else {
                    max_zeros = Math.max(max_zeros, zeros);
                }
                zeros = 0;
            }
        } 
        suf_zeros = zeros;
        return Math.max(Math.max(pre_zeros, suf_zeros), (max_zeros + 1) / 2);
    }
