class Solution {
public:

     //idea is to make MSB as one in each row then move in colums that if zeros>1s toggle else don't
    int toDecimal(vector<vector<int>>& grid,int m,int n){
        int ans=0;
        for(int i=0;i<m;i++){
            int curr=0;
            int mul=1;
            for(int j=n-1;j>=0;j--){
                curr+=(grid[i][j]*mul);
                mul*=2;
            }
            ans+=curr;
        }
        return ans;
    }
    bool count(vector<vector<int>>& grid, int col,int m){
        int cnt=0;
        for(int i=0;i<m;i++){
            if(grid[i][col]==0){
                cnt++;
            }
        }
        return cnt>(m-cnt);

    }
    void toggleRow(vector<vector<int>>& grid,int r,int m,int n){
        for(int i=0;i<n;i++){
            if(grid[r][i]==1){
                grid[r][i]=0;
            }else{
                grid[r][i]=1;
            }
        }
    }
    void toggleCol(vector<vector<int>>& grid,int c,int m,int n){
        for(int i=0;i<m;i++){
            if(grid[i][c]==1){
                grid[i][c]=0;
            }else{
                grid[i][c]=1;
            }
        }
    }
    int matrixScore(vector<vector<int>>& grid) {

        int m=grid.size(),n=grid[0].size();
        for(int i=0;i<m;i++){
            if(grid[i][0]==0){
                toggleRow(grid,i,m,n);
            }
        }
        for(int i=1;i<n;i++){
            if(count(grid,i,m)){
                toggleCol(grid,i,m,n);
            }
        }
        return toDecimal(grid,m,n);

    }
};,167,https://leetcode.com/problems/score-after-flipping-matrix,https://leetcode.com/problems/score-after-flipping-matrix/solutions/3068127/0ms-runtime-beats-100/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    void markParents(TreeNode* root,unordered_map<TreeNode*,TreeNode*>& parent) {
        if(root == NULL)
            return;

        queue<TreeNode*> q;
        q.push(root);

        while(!q.empty()) {
            TreeNode* curr = q.front();
            q.pop();

            if(curr->left) {
                q.push(curr->left);
                parent[curr->left] = curr;
            }

            if(curr->right) {
                q.push(curr->right);
                parent[curr->right] = curr;
            }
        }
    }

    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
        unordered_map<TreeNode*,TreeNode*> parent;
        markParents(root,parent);


        queue<TreeNode*> q;
        unordered_map<TreeNode*,bool> visited;


        visited[target] = true;
        q.push(target);
        int currLevel = 0;

        while(!q.empty()) {
            int size = q.size();

            if(currLevel == k) 
                break;

            currLevel++;

            for(int i=0;i<size;i++) {
                TreeNode* curr = q.front();
                q.pop();

                if(curr->left && !visited[curr->left]) {
                    q.push(curr->left);
                    visited[curr->left] = true;
                }


                if(curr->right && !visited[curr->right]) {
                    q.push(curr->right);
                    visited[curr->right] = true;
                }


                if(parent[curr] && !visited[parent[curr]]) {
                    q.push(parent[curr]);
                    visited[parent[curr]] = true;
                }
            }
        }


        vector<int> result;

        while(!q.empty()) {
            TreeNode* curr = q.front();
            q.pop();
            result.push_back(curr->val);
        }

        return result;
    }
};,90,https://leetcode.com/problems/all-nodes-distance-k-in-binary-tree,https://leetcode.com/problems/all-nodes-distance-k-in-binary-tree/solutions/3984086/easy-bfs-solution-explanation-c/

