class Solution {
public:

    int cnt = 0;

//helper fncn is used to calculate number of possibilities when number of digits == max possible digits
    void helper (string &maxm, vector<string> &digits, int i, int &numofdigits, int &maxdigits) {

        if (i==maxdigits) {cnt++; return;}
        for (string str: digits) {
            //note that str[0] is the digit we want in its character form, for comparison purposes.. 
        //otherwise you can also convert str into int and then compare that int with max[i]-'0'.
            if (str[0] < maxm[i]) cnt+= pow(numofdigits, maxdigits-1-i);
            else if (str[0] > maxm[i]) return;
            else helper (maxm, digits, i+1, numofdigits, maxdigits);
        }
    }

    int atMostNGivenDigitSet(vector<string>& digits, int n) {
        string maxm = to_string(n);
        int maxdigits = maxm.size();
        int numofdigits = digits.size();

        for (int i=1; i<maxdigits; i++) { //counting the combinations when number of digits < number of digits in 'n'
            cnt += pow(numofdigits, i);
        }

        helper (maxm, digits, 0, numofdigits, maxdigits); //when num of digits == maxdigits

        return cnt;
    }
