class Solution {
    public int[] numMovesStones(int a, int b, int c) {

        int x = Math.min(a,Math.min(b,c));
        int y = Math.max(a,Math.max(b,c));
        int z=0;

        // sorting the elements
        if(x==a){
            if(y==b) z=c;
            else z=b;
        }else if(x==b){
            if(y==a) z=c;
            else z=a;
        }else{
            if(y==b) z=a;
            else z=b;
        }

        a=x;
        b=z;
        c=y;
        int ans[] = new int[2];
        if(c-a==2){
            ans[0]=0;
            ans[1]=0;
            return ans;
        }else if(b-a==1 || c-b==1 || b-a==2 || c-b==2){
            ans[0]=1;
        }else{
            ans[0]=2;
        }

        int k = (b-a-1)+(c-b-1);
        ans[1]=k;
        return ans;
    }
