/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    // Initialize the sum vector with INT_MIN at index 0
    vector<int> sum = {INT_MIN};

    // Depth-first search function to calculate the sum at each level
    void dfs(TreeNode* Node, int level){
        // Base case: If the current node is null, return
        if (Node == NULL) return;

        // If the sum vector size is equal to the current level,
        // add the node's value to the sum vector
        if (sum.size() == level) sum.push_back(Node->val);
        else sum[level] += Node->val;

        // Recursively call the dfs function for the left and right child nodes
        dfs(Node->left, level+1);
        dfs(Node->right, level+1);
    }

    // Main function to find the level with the maximum sum in the binary tree
    int maxLevelSum(TreeNode* root) {
        // Call the dfs function to calculate the sum at each level
        dfs(root, 1);

        // Find the maximum element in the sum vector
        // and return its index
        return max_element(sum.begin(), sum.end()) - sum.begin();
    }
};
