class Solution {
public:
    int makeArrayIncreasing(vector<int>& arr1, vector<int>& arr2) {
        sort(arr2.begin(), arr2.end());
        arr2.erase(unique(arr2.begin(), arr2.end()), arr2.end());
        int n = arr1.size();
        int m = arr2.size();
        vector<vector<int>> dp (n+1, vector<int>(m+1));
        dp[0][0] = 0;
        for (int j = 1; j <= m; ++j) dp[0][j] = 2*n;
        for (int i = 1; i <= n; ++i) {
            dp[i][0] = 2*n;
            if (i == 1 || arr1[i-1] > arr1[i-2]) dp[i][0] = dp[i-1][0];
            int cur_min = 2*n;
            for (int j = 1; j <= m; ++j) {
                if (i == 1 || arr1[i-1] > arr2[j-1])
                    dp[i][0] = min(dp[i][0], dp[i-1][j]);
                dp[i][j] = cur_min + 1;
                if (i == 1 || arr2[j-1] > arr1[i-2]) dp[i][j] = min(dp[i][j], dp[i-1][0] + 1);
                cur_min = min(cur_min, dp[i-1][j]);
            }
        }
        int ans = 2*n;
        for (int j = 0; j <= m; ++j) {
            ans = min(ans, dp[n][j]);
        }
        return (ans > n) ? -1 : ans;
    }
};,80,https://leetcode.com/problems/make-array-strictly-increasing,https://leetcode.com/problems/make-array-strictly-increasing/solutions/3648018/c-dynamic-programming/

class Solution {
public:
    int ok(long long n, long long a, long long b, long long c) {
        // numbers (1 to n) divisble by a = n / a
        // numbers (1 to n) divisble by b = n / b
        // numbers (1 to n) divisble by c = n / c
        // exclude overlapping counts for a and b = n / lcm(a, b)
        // exclude overlapping counts for b and c = n / lcm(b, c)
        // exclude overlapping counts for a and c = n / lcm(a, c)
        // include those covered by all a, b and c = n / lcm(a, lcm(b, c))  

        // Set theory Formula: 
        // a + b + c - a ∩ c - a ∩ b - b ∩ c + a ∩ b ∩ c
        return (int) n / a + n / b + n / c 
        - n / lcm(a, b)
        - n / lcm(b, c)
        - n / lcm(a, c)
        + n / lcm(a, lcm(b, c));
    }

    int nthUglyNumber(int n, int a, int b, int c) {
        // init possible range [1, 2 * 10 ^ 9]
        int l = 1, r = 2e9;
        while (l < r) {
            // get the middle one
            // for even number of elements, take the lower one
            int m = l + (r - l) / 2;
            // exclude m
            if (n > ok(m, a, b, c)) l = m + 1;
            // include m
            else r = m;
        }
        return l;
    }
};,158,https://leetcode.com/problems/ugly-number-iii,https://leetcode.com/problems/ugly-number-iii/solutions/2402964/leetcode-the-hard-way-inclusive-exclusive-binary-search/

class Solution {
public:
    const long long mod = 1e9 + 7;
    int n;
    vector<vector<int>> dp;// (length, ends with jth vowel)

    int f(int i, int j) {
        if (i == n) return 1;
        if (dp[i][j] != -1) return dp[i][j];
        long long ans = 0;

        switch (j) {
            case 0: ans=(ans + f(i+1, 1)) % mod;
                break; // 'a' may only be followed by an 'e'

            case 1: ans=(ans + f(i+1, 0) + f(i+1, 2)) % mod;
                break; // 'e' may only be followed by an 'a' or an 'i'

            case 2: ans=(ans+f(i+1,0)+f(i+1,1)+f(i+1,3)+f(i+1,4))%mod;
                break; // 'i' may not be followed by another 'i'

            case 3: ans = (ans+f(i+1,2) + f(i+1,4)) % mod;
                break; // 'o' may only be followed by an 'i' or a 'u'

            case 4: ans = (ans+f(i+1, 0)) % mod;
                break; // 'u' may only be followed by an 'a'
        }
        return dp[i][j] = ans;
    }

    int countVowelPermutation(int n) {
        this->n = n;
        dp.assign(n + 1, vector<int>(5, -1));
        long long ans = 0;
        for (int j = 0; j < 5; j++)
            ans = (ans + f(1,j)) % mod;// starting from length=1
        return ans;
    }
};
