class Semaphore{
    mutex m;
    condition_variable cv;
    int cnt;
public:
    Semaphore(){}
    Semaphore(int c):cnt(c){};
    void setCount(int a){
        cnt=a;
    }
    inline void signal(){
        unique_lock<mutex> lock(m);
        cnt++;
        if(cnt<=0) cv.notify_all();
    }
    inline void wait(){
        unique_lock<mutex> lock(m);
        cnt--;
        while(cnt<0) cv.wait(lock);
    }
};
