        lock_guard<mutex> lock(m);
        fork[(philosopher+1)%5].wait();
        fork[philosopher].wait();
        pickLeftFork();
        pickRightFork();
        eat();
        putLeftFork();
        fork[(philosopher+1)%5].signal();
        putRightFork();
        fork[philosopher].signal();
    }
