var maxLength = function(arr) {
    let ans = 0;

  /**
   * check if the current String only has unique characters
   * @param {string} str
   */
  let isUnique = (str) => {
    let bits = 1 << 26;
    for (let ch of str) {
      let index = ch.charCodeAt(0) - 97;
      //condition to check if all unique or not
      if (bits & (1 << index)) {
        return false;
      }
      //set the bit
      bits |= 1 << index;
    }
    return true;
  };

  /**
   * backtrack function
   * @param {number} index
   * @param {string} prevStr
   */
  let getAns = (index, prevStr) => {
    ans = Math.max(ans, prevStr.length);
    if (index == arr.length) {
      return;
    }
    for (let i = index; i < arr.length; i++) {
      const newStr = prevStr + "" + arr[i];
      if (isUnique(newStr)) {
        getAns(i + 1, newStr);
      }
    }
  };

  getAns(0, "");
  return ans;
};,81,https://leetcode.com/problems/maximum-length-of-a-concatenated-string-with-unique-characters,https://leetcode.com/problems/maximum-length-of-a-concatenated-string-with-unique-characters/solutions/4382870/javascript-using-bit-manipulation-and-backtracking-clean-code/

class Solution {
public:
	vector<vector<int>> reconstructMatrix(int upper, int lower, vector<int>& colsum) {
		int n=colsum.size();
		vector<vector<int>>mat(2,vector<int>(n,0));
		if(lower+upper!=accumulate(colsum.begin(),colsum.end(),0))return {};
		for(int j=0;j<n;j++){
			if(colsum[j]==2){
				mat[1][j]=mat[0][j]=1;
				colsum[j]=0;
				upper--;
				lower--;
			}        
		}
//      Upper
		for(int j=0;j<n;j++){
			if(upper && colsum[j]){
				mat[0][j]=1;
				upper--;
				colsum[j]--;
			}    
		}
//      Lower
		for(int j=0;j<n;j++){
			if(lower && colsum[j]){
				mat[1][j]=1;
				lower--;
				colsum[j]--;
			}    
		}
		if(lower || upper)return {};
