class Solution {
public:
    int maxSumDivThree(vector<int>& nums) {
        int a = INT_MAX,b = INT_MAX,c=INT_MAX,d=INT_MAX,s=0;
        for(auto &i: nums){
            s += i;
            if(i%3==1){
                if(i<a){
                    b= a;
                    a = i;
                }else if(i<b){
                    b = i;
                }
            }else if(i%3==2){
                if(i<c){
                    d = c;
                    c = i;
                }else if(i<d){
                    d = i;
                }
            }
        }
        if(s%3==0)return s;
        if(s%3 == 1){
            int ans = 0;
            if(a != INT_MAX){
                ans = s-a;
            }
            if(d != INT_MAX && c != INT_MAX)ans = max(ans,s-d-c);
            return ans;
        }
        int ans = 0;
        if(c != INT_MAX)ans =  s-c;
        if(a != INT_MAX && b != INT_MAX)ans = max(ans, s-a-b);
        return ans;
    }
