class Solution {
public:
    int removeCoveredIntervals(vector<vector<int>>& intervals) {
        int result = intervals.size();

        sort(intervals.begin(), intervals.end(), [](const auto& a, const auto& b) {
            return a[0] < b[0];
        });

        for (int i = 0; i < intervals.size()-1; i++) {
            // ex: (1, 2) & (1, 4) -> remove (1, 2)
            if (intervals[i][0] == intervals[i+1][0]) {
                if (intervals[i][1] < intervals[i+1][1]) {
                    result--;
                    continue;
                }
            }

            // ex: (1, 4) & (2, 8) -> seperate intervals
            if (intervals[i][1] < intervals[i+1][1]) continue;

            // ex: (2, 8) & (3, 6) -> remove (3, 6)
            intervals[i+1] = intervals[i];
            result--;
        }

        return result;
    }
};,119,https://leetcode.com/problems/remove-covered-intervals,https://leetcode.com/problems/remove-covered-intervals/solutions/3561311/c-clean-simple/

