    def isPossibleDivide(self, nums, k):
        if len(nums) % k != 0:
            return False

        map = {}
        for num in nums:
            map[num] = map.get(num, 0) + 1

        nums.sort()

        for num in nums:
            if map[num] > 0:
                for i in range(num+1, num+k):
                    if map.get(i, 0) == 0:
                        return False
                    map[i] -= 1
                map[num] -= 1

        return True
