// This code is an implementation of a function called kWeakestRows that finds the k weakest rows in a given matrix 'mat'.
// The weakness of a row is determined by the number of ones it contains.

// The code uses a priority queue (max heap) to keep track of the k weakest rows efficiently.

// Why Max Heap?
// The code uses a max heap (priority_queue) because it wants to keep track of the k smallest values, and a max heap allows us to efficiently maintain the k smallest elements.
// Since each push and pop operation on a max heap costs O(log k) time (where k is the size of the heap), it is suggested to minimize the number of such operations.

class Solution {
public:
    using int2 = pair<int, int>;
    vector<int> kWeakestRows(vector<vector<int>>& mat, int k) {
        int n = mat.size();
        priority_queue<int2> pq; // Create a max heap to store pairs of (number of ones, row index).

        // Iterate through the first k rows and calculate the number of ones in each row.
        for (int i = 0; i < k; i++) {
            int ones = accumulate(mat[i].begin(), mat[i].end(), 0);
            pq.emplace(ones, i); // Push the pair (number of ones, row index) onto the max heap.
        }

        // Iterate through the remaining rows (from k to n-1).
        for (int i = k; i < n; i++) {
            int ones = accumulate(mat[i].begin(), mat[i].end(), 0);
            int wt = pq.top().first; // Get the number of ones of the weakest row (at the top of the max heap).

            // If the current row has fewer ones than the weakest row, replace the weakest row in the max heap with the current row.
            if (ones < wt) {
                pq.emplace(ones, i); // Push the pair (number of ones, row index) onto the max heap.
                pq.pop(); // Pop the weakest row from the max heap.
            }
        }

        vector<int> ans(k, 0);

        // Extract the row indices of the k weakest rows from the max heap (in reverse order).
        for (int i = k - 1; i >= 0; i--) {
            ans[i] = pq.top().second;
            pq.pop();
        }

        return ans; // Return the indices of the k weakest rows in the matrix.
    }
};
