    int maxEvents(vector<vector<int>>& events) {
        sort(events.begin(),events.end(),cmp);
        set<int>days;
        int cnt=0;
        for(int i= 1 ;i<=100000;++i)
        {
            days.insert(i);
        }
        for(const auto & event : events)
        {
            int s = event[0];
            int e = event[1];
            auto it = days.lower_bound(s);
            if(it == days.end() || *it >e)
            {
                continue;
            }
            else
            {
                ++cnt;
                days.erase(it);
            }
        }
        return cnt;
    }
