class Solution {
    public String largestMultipleOfThree(int[] digits) {
        int[] D = new int[10];
        int sum = 0;
        for(int d : digits){
            D[d]++;
            sum += d;
        }
        int mod = sum % 3, N = digits.length;
        while(sum % 3 != 0){
            if(mod == 1){
                if(D[1] > 0){
                    D[1]--; sum -= 1;
                }
                else if(D[4] > 0){
                    D[4]--; sum -= 4;
                }
                else if(D[7] > 0){
                    D[7]--; sum -= 7;
                }
                else if(D[2] > 0){
                    D[2]--; sum -= 2;
                }
                else if(D[5] > 0){
                    D[5]--; sum -= 5;
                }
                else if(D[8] > 0){
                    D[8]--; sum -= 8;
                }
                else return "";
            }
            else if(mod == 2){
                if(D[2] > 0){
                    D[2]--; sum -= 2;
                }
                else if(D[5] > 0){
                    D[5]--; sum -= 5;
                }
                else if(D[8] > 0){
                    D[8]--; sum -= 8;
                }
                else if(D[1] > 0){
                    D[1]--; sum -= 1;
                }
                else if(D[4] > 0){
                    D[4]--; sum -= 4;
                }
                else if(D[7] > 0){
                    D[7]--; sum -= 7;
                }
                else return "";
            }
            N--;
        }
        if(sum == 0)
            return D[0] == 0? "" : "0";
        char[] res = new char[N];
        for(int i = 9, k = -1; i > -1; i--)
            for(int j = 0; j < D[i]; j++)
                res[++k] = (char)(i + 48);
        return String.valueOf(res);
    }
