class UndergroundSystem {
    unordered_map<int, pair<string, int>> in;    
// Maps passenger ID to their check-in station name and time

    unordered_map<string,unordered_map<string, vector<int>>> time;
// Maps start station to end station and a vector of travel times

public:   
    UndergroundSystem() {
        // Constructor does not perform any specific actions
    }

    void checkIn(int id, string stationName, int t) {
        in[id]={stationName, t};    
// Store check-in station name and time for the passenger ID
    }

    void checkOut(int id, string stationName, int t) {
        auto& [startStation, t0]=in[id];    
// Retrieve check-in station name and time for the passenger ID

        time[startStation][stationName].push_back(t-t0);    
// Calculate travel time and add it to the vector of travel times for the start and end stations
    }

    double getAverageTime(string startStation, string endStation) {
        double av=0;    // Variable to store the total travel time
        for(auto t: time[startStation][endStation]) 
            av+=t;    // Sum up all travel times between the start and end stations
        av/=time[startStation][endStation].size();    // Calculate the average travel time
        return av;    // Return the average travel time
    }
};
