class Solution {
public:
    vector<int> fib;

    void populateFib() {
        fib.push_back(1);
        fib.push_back(1);
        int i = 1, j = 1;
        while(fib.back() <= (int)(1e9)) {
            int newnum = i+j;
            i = fib.back(), j = newnum;
            fib.push_back(newnum);
        }
    }

    int search(int num, int i, int j) {
        if(i > j) {
            return -1;
        }

        int mid = (i+j)/2;
        if(fib[mid] == num) return mid;
        else if(fib[mid] > num) return search(num,i,mid-1);
        int poss = search(num,mid+1,j);
        if(poss == -1) return mid;
        return poss;
    }

    int findMinFibonacciNumbers(int n) {
        populateFib();
        int cnt = 0;
        while(n) {
            n -= fib[search(n,0,fib.size())];
            cnt++;
        } 

        return cnt;
    }
};,71,https://leetcode.com/problems/find-the-minimum-number-of-fibonacci-numbers-whose-sum-is-k,https://leetcode.com/problems/find-the-minimum-number-of-fibonacci-numbers-whose-sum-is-k/solutions/3989990/find-the-minimum-number-of-fibonacci-numbers-whose-sum-is-k/

class Solution {

    static long helper(int n , long dp[]){
        if(n==1 || n==2) return dp[n-1] = 1;

        if(dp[n-1]!=0) return dp[n-1];
        else return dp[n-1] = helper(n-1,dp)+helper(n-2,dp);
    }
    public int findMinFibonacciNumbers(int k) {
        long dp[] = new long[45];
        long x = (long)k;

        helper(45,dp);  // finding first 45 fibo numbers as 45th number is just greater than 10^9 which is the limit of k

        long ans = 0;
        int idx = -1;
        int st = 44;
        while(x>0){
            for(int i=st; i>=0; i--){
                if(dp[i]<=x){
                   idx = i;
                   break;
                }
            }
            x=x-dp[idx];
            ans++;
            st = idx;
        }
        return (int)ans;
    }
