class Solution {
public:
    int findMinFibonacciNumbers(int k) {
        // Intution
        // The idea in here is really very simple. We will keep all the fibonacci numbers in the vector till the value of the last fibonacci number is greater than or equal to n. Then we will pass the vector into solution where every time either we can choose or we can skip.

        int a = 1;
        int b = 1;

        vector<int> fibNumbers;

        fibNumbers.push_back(a);

        int c = 2;

        while(c <= k){
            fibNumbers.push_back(c);
            a = b;
            b = c;
            c = a + b;
        }

        int coins = 0;

        int size = fibNumbers.size() - 1;

        while(size >= 0 and k){
            if(fibNumbers[size] <= k){
                coins += (k / fibNumbers[size]);
                k = k - (k / fibNumbers[size]) * fibNumbers[size];
            }
            size -= 1;
        }

        return coins;

    }
};,89,https://leetcode.com/problems/find-the-minimum-number-of-fibonacci-numbers-whose-sum-is-k,https://leetcode.com/problems/find-the-minimum-number-of-fibonacci-numbers-whose-sum-is-k/solutions/3890413/c-finding-fibonacci-numbers-minimum-coins-change-problem-o-k-solution-nice-intution/

class Solution {
public:
    int mod = 1e9+7;
    int solve(string &str,int &k,vector<int> &dp,int &n,int s){
        if(s==n)return 1;
        if(str[s]=='0')return 0;
        if(dp[s] != -1)return dp[s];
        long int y = 0,x = 0;
        for(int i = s; i < n; i++){
            if(x*10+(str[i]-'0')<=k){
                x = x*10+(str[i]-'0');
                y = (y+solve(str,k,dp,n,i+1))%mod;
            }else{
                break;
            }
        }
        return dp[s] = y;
    }
    int numberOfArrays(string s, int k) {
        int n = s.length();
        vector<int> dp(n+1,-1);
        return solve(s,k,dp,n,0);
    }
};,48,https://leetcode.com/problems/restore-the-array,https://leetcode.com/problems/restore-the-array/solutions/3446431/c-memoization-easy-to-understand/

