/* dp[hat][mask] represents the number of ways to assign the first 'hat'
 * hats to the available persons.
 * Note : Available persons have the same index as the set bit
 * One based index for hat, zero based for persons
 */

int Solution :: numberWays(vector<vector<int>> &mat)
{
	int n = mat.size();

	// All persons are available
	int biggestMask = (1 << n) - 1;

	vector<vector<int>> pref(max_hat + 1);

	// Find all the persons interested in one hat
	for(int i = 0; i < n; i++)
		for(auto h_ind : mat[i])
			pref[h_ind].push_back(i);

	vector<vector<int>> dp(max_hat + 1, vector<int>(biggestMask + 1, 0));

	// Only one base case. No Hats, No persons to fill. Done!
	dp[0][0] = 1;

	for(int hat = 1; hat <= max_hat; hat++)
	{
		for(int mask = 0; mask <= biggestMask; mask++)
		{
			// Dont' use this hat
			dp[hat][mask] = add(dp[hat][mask], dp[hat - 1][mask]);

			// Use this hat on available persons who prefer it
			for(auto p_ind : pref[hat])
				if( mask & (1 << p_ind) )
					dp[hat][mask] = add(dp[hat][mask], dp[hat - 1][mask xor (1 << p_ind)]);
		}
	}

	return dp[max_hat][biggestMask];
},191,https://leetcode.com/problems/number-of-ways-to-wear-different-hats-to-each-other,https://leetcode.com/problems/number-of-ways-to-wear-different-hats-to-each-other/solutions/608599/yeah-well-just-make-me-cry-during-the-interview-an-optimised-iterative-dp/

