class Solution {
public:
    vector<string> buildArray(vector<int>& target, int n) {
        vector<string> ans;  // Initialize a vector of strings to store the result.
        int temp = 0;  // Initialize a temporary variable to keep track of the elements in the 'target' array.
        int i = 1;  // Initialize an integer 'i' to represent the current number.

        // Continue the loop until all elements in the 'target' array are processed.
        while (temp < target.size()) {
            if (target[temp] == i) {
                ans.push_back("Push");  // Simulate pushing the current number onto the stack.
                temp++;  // Move to the next element in the 'target' array.
            } else {
                ans.push_back("Push");  // Simulate pushing the current number onto the stack.
                ans.push_back("Pop");   // Simulate popping an element from the stack (even though it's not the target element).
            }
            i++;  // Move to the next number.
        }

        return ans;  // Return the 'ans' vector containing the sequence of "Push" and "Pop" instructions.
    }
};


