        {
            sum+=a[i];
            if(mp.find(sum-t)!=mp.end())
            {
                lsz = min(lsz,i-mp[sum-t]);
            }


            if(mp.find(sum+t)!=mp.end() && lsz !=INT_MAX)
            {
                res = min(res,mp[sum+t]-i + lsz );
            }
        }

        return res==INT_MAX?-1:res;
    }
