  a.sort((a, b) => a - b)
  // now                           min is left most, max is right most
  // also for  every subsequence - min is left most, max is right most

  let count = 0n // BigInt due to many subsequences
  for (let L = 0, R = n - 1; L < n; L++) {
    for (; L <= R && a[R] + a[L] > target; R -= 1) {
    }
    if (L > R) break // no elements
    count += modPowBigInt(2, R - L, MODn) // 2 power num of elements, subsequences
    count %= MODn
  }
  return count
}

function modPowBigInt(base, p, MODn) {
  // Math.pow with mod for BigInt
  return modPow(BigInt(base), BigInt(p))

  function modPow(base, p) {
    if (p === 0n) return 1n
    if (p === 1n) return base
    if (p % 2n === 1n) return (modPow(base, p - 1n) * base) % MODn
    let half = modPow(base, p / 2n)
    return (half * half) % MODn
  }
}
