class Solution:
    def solve(self, locations, currCity, remainingFuel):
        if remainingFuel < 0:
            return 0
        if self.dp[currCity][remainingFuel] != -1:
            return self.dp[currCity][remainingFuel]

        ans = 1 if currCity == self.finish else 0
        for nextCity in range(self.n):
            if nextCity != currCity:
                ans = (ans + self.solve(locations, nextCity,
                        remainingFuel - abs(locations[currCity] - locations[nextCity]))) % 1000000007

        self.dp[currCity][remainingFuel] = ans
        return ans

    def countRoutes(self, locations, start, finish, fuel):
        self.n = len(locations)
        self.dp = [[-1] * (fuel + 1) for _ in range(self.n)]
        self.finish = finish

        return self.solve(locations, start, fuel)
