class Solution {
    /* 
    This is a union-find (aka disjoint-set)n problem. 
    We can recognize its a union-find because we have a bunch of different elements that are
    originally unconnected to each other. Then we have to check if pairs of these elemnts 
    are actually part of the same set

    Therefore, we place each element into it's own individual set, and repeatedly join (union/unite)
    the sets whenever we can. Eventually, we have sets of DISJOINT SETS. sets that are disjoint from
    one another.

    Then it becomes very easy for us to check if queries are connected. Just check if they're
    part of the same set. After building the union-find data structure, this can be done in constant time
    for each query. 
    */ 
    private int[] component;
    private int[] rank;
    private int distinctComponents;

    // Please learn more about union-find and disjoint set to better understand this solution. 
    // Search for "William Fiset Union Find" He has 3 videos on it
    public List<Boolean> areConnected(int n, int threshold, int[][] queries) {
        int len = queries.length;
        component = new int[n+1]; // Each component/set is connected if component[i] eventually points to the same i. (See findComponent method)
        rank = new int[n+1]; // To decide who should be the parent. 
        distinctComponents = n; // We start with n sets/components
        for (int i = 0; i <= n; i++) {
            component[i] = i; //Each component/set originally only consists of it's 1 element
            rank[i] = 0; // Rank starts at 0
        }
        // For every number from threshold to n, we unite all of its multiples up to n. 
        // We start with threshold since anything smalle rthan it shouldn't be part of a set, it can't be connected to anything
        for (int i = threshold+1; i <= n; i++) {
            int m = 1; // m is multiple, starts at 1. 
            while (i*m <= n) {// Unite i, with all of it's multiples up to n 
                unite(i, i*m);  // By uniting, we make them part of the same set/group/component./
                m++; // So if i was 4, we'd do 4*1, 4*2, 4*3, etc. As long as (4*m) was less than n/
                // This makes sense because 4,8,12,16 all have such a number z (which is 4) that they're all divisible by. 
            }
        }

        List<Boolean> l = new ArrayList<>();
        for (int[] q : queries) {
            l.add(connected(q[0], q[1]));// Finally just go through all the queries and check if they're connected. 
        }
        return l;
    }

    // does union and returns true if a and b were in different components else return false
    private boolean unite(int a, int b) {
        int x = findComponent(a); //a is part of a set. Every set has a set parent. X is that set's parent
        int y = findComponent(b); // in this case, y is the parent of the set that b is in.
        if (x != y) {
            // The following code just ensures the parent is always the one with the higher rank
            if (rank[x] < rank[y]) {
                component[x] = y; // Set y as the parent of x, now set X joined set Y, so they're all set Y
            }
            else {
                if (rank[x] == rank[y])
                    rank[x]++;
                component[y] = x; // Same as above
            }
            distinctComponents--;// We connected 2 components into 1, so we're down 1 distinct component.
            return true;
        }
        else {
            // if x==y, then they're already part of the same set/component.
            return false;
        }
    }

    private int findComponent(int a) {
        if (component[a] != a) { // If component[a] == a, that means we finally hit the parent of the set, and can return it
            // if it isn't then we just find the parent
            component[a] = findComponent(component[a]);
        }
        return component[a];
    }

    private boolean connected(int a, int b) {
        int x = findComponent(a);
        int y = findComponent(b);
        return x == y; // As mentioned, elements are connected if they're part of the same component/set, meaning they have the same parent.
    }

    private boolean united() {
        return distinctComponents == 1;
    }

