        for(int i = 0;i<n;i++){
            sort(matrix[i].begin(), matrix[i].end());

            for(int j=0;j<m;j++){
                int h = matrix[i][j];
                int w = m-j;
                ans = max(ans, h*w);
            }
        }
        return ans;
    }
