class Solution {
public:
    bool check(string s){
        vector<int> t1(26, 0), t2(26, 0); 
        for(int i=0; i<s.length(); i++) if(s[i] >= 'a' && s[i] <= 'z') t1[s[i] - 'a']++; 
        for(int i=0; i<s.length(); i++) if(s[i] >= 'A' && s[i] <= 'Z') t2[s[i] - 'A']++; 

         for(int i=0; i<26; i++){
            if(t1[i] == 0 && t2[i] == 0) continue; 
            else if(t1[i] == 0 && t2[i] > 0) return false;  
            else if(t1[i] > 0 && t2[i] == 0) return false; 
        } 

        return true; 
    }

    string longestNiceSubstring(string s) {

        if(s == "") return ""; 
        if(check(s)) return s; 

        unordered_map<char,int> m; 
        vector<int> t1(26, 0), t2(26, 0); 
        for(int i=0; i<s.length(); i++) if(s[i] >= 'a' && s[i] <= 'z') t1[s[i] - 'a']++; 
        for(int i=0; i<s.length(); i++) if(s[i] >= 'A' && s[i] <= 'Z') t2[s[i] - 'A']++; 


        for(int i=0; i<26; i++){
            if(t1[i] == 0 && t2[i] == 0) continue; 
            else if(t1[i] == 0 && t2[i] > 0) m[i + 'A']++; 
            else if(t1[i] > 0 && t2[i] == 0) m[i + 'a']++; 
        } 



        vector<string> ans; string temp = ""; 
        for(int i=0; i<s.length(); i++){
            if(m.find(s[i]) == m.end()) temp += s[i]; 
            else {
                ans.push_back(temp); temp = ""; 
            }

        }
        if(temp != "") ans.push_back(temp); 

        string kk = ""; 

        for(int i=0; i<ans.size(); i++){
            if(ans[i] == "") continue; 
            string t = longestNiceSubstring(ans[i]);
            if(t == "") continue;  
            if(kk == "" || kk.length() < t.length()) kk = t; 

        }

        return kk; 


    }
};,122,https://leetcode.com/problems/longest-nice-substring,https://leetcode.com/problems/longest-nice-substring/solutions/3700228/easy-solution/

class Solution {
public:
    string normalize(vector<int> &nums)
    {
        string ans = "";
        for(int i=0;i<nums.size();i++)
        {
            ans+=to_string(nums[i]);
            ans+="#";
        }
        ans.pop_back();
        return ans;
    }
    bool canChoose(vector<vector<int>>& groups, vector<int>& nums) {
        string base = normalize(nums);
        int prevpos = 0;
        bool flag = true;
        for(int i=0;i<groups.size();i++)
        {
            vector<int> v = groups[i];
            string tofind = normalize(v);
            if(base.find(tofind,prevpos) != string::npos)
            {
                int currpos = base.find(tofind,prevpos);
                bool check = true;
                if(currpos!=0 && base[currpos-1]!='#')
                {
                    check = false;
                }
                if(currpos+tofind.length()!=base.length() && base[currpos+tofind.length()]!='#')
                {
                    check = false;
                }
                if(check==false)
                {
                    flag = false;
                    break;
                }
                if(currpos<prevpos)
                {
                    flag = false;
                    break;
                }
                else
                {
                    prevpos= currpos+tofind.length();
                }
            }
            else
            {
                flag = false;
                break;
            }
        }

        return flag;
    }
