class Solution {
public:
    int m, n;
    int memo[1000][1000];
    int maximumScore(vector<int>& nums, vector<int>& muls) {
        n = nums.size();
        m = muls.size();
        memset(memo, -1, sizeof(memo));
        return dp(0, 0, nums, muls);
    }
    int dp(int l, int i, vector<int>& nums, vector<int>& muls) {
        if (i == m) return 0; // Picked enough m elements
        if (memo[l][i] != -1) return memo[l][i];
        int pickLeft = dp(l+1, i+1, nums, muls) + nums[l] * muls[i]; // Pick the left side
        int pickRight = dp(l, i+1, nums, muls) + nums[n-(i-l)-1] * muls[i]; // Pick the right side
        return memo[l][i] = max(pickLeft, pickRight);
    }
};,33,https://leetcode.com/problems/maximum-score-from-performing-multiplication-operations,https://leetcode.com/problems/maximum-score-from-performing-multiplication-operations/solutions/1075469/java-c-python-3-top-down-dp-o-m-2-clean-concise/

var minElements = function (nums, limit, goal) {
  let sum = nums.reduce((sum, e) => sum + e, 0)

  let cc = 0
  for (let lim = limit; lim >= 1; lim--) {
    let need = goal - sum
    if (need === 0) return cc

    if (lim <= Math.abs(need)) {
      let q = Math.abs(Math.trunc(need / lim))
      cc += q
      sum += q * (need < 0 ? -lim : lim)
    }
  }
  return cc
};
