class Solution {
public:
    int reinitializePermutation(int n) {
        int i, count=1;
        vector<int> initial_arr;
        vector<int> temp;
        vector<int> new_arr;
        for(i=0 ; i<n ; i++)
        {
            initial_arr.push_back(i);
        }
        for(i=0 ; i<n ; i++)
        {
            if(i%2==0)
            {
                new_arr.push_back(initial_arr[i/2]);
                temp.push_back(initial_arr[i/2]);
            }
            else
            {
                new_arr.push_back(initial_arr[n/2 + (i-1)/2]);
                temp.push_back(initial_arr[i/2]);
            }
        }
        if(new_arr==initial_arr)
        {
            return 1;
        }
        while(true)
        {
            for(i=0 ; i<n ; i++)
            {
                if(i%2==0)
                    temp[i] = new_arr[i/2];
                else
                    temp[i] = new_arr[n/2 + (i-1)/2];
            }
            new_arr.clear();
            copy(temp.begin(), temp.end(), back_inserter(new_arr));
            count++;
            if(new_arr==initial_arr)
                break;
        }
        return count;
    }
};,55,https://leetcode.com/problems/minimum-number-of-operations-to-reinitialize-a-permutation,https://leetcode.com/problems/minimum-number-of-operations-to-reinitialize-a-permutation/solutions/3525555/minimum-number-of-operations-to-reinitialize-a-permutation-solution-in-c/

class Solution:
    def maxNiceDivisors(self, n):
        M = 10**9 + 7
        if n <= 3: return n
        if n % 3 == 0: return pow(3, n//3, M)
        if n % 3 == 1: return (pow(3, (n-4)//3, M) * 4) % M
